import test from 'node:test';import assert from 'node:assert/strict';import {book} from './solution.mjs';
test("empty",async()=>assert.deepEqual(await book({"range_start": "2024-01-07T00:00Z", "range_end": "2024-01-08T00:00Z", "rooms": ["a"], "transitions": {"a": {"a": 0}}, "meetings": [], "blocks": []}),{"value": 0, "count": 0, "bookings": []}));
test("simple",async()=>assert.deepEqual(await book({"range_start": "2024-01-07T00:00Z", "range_end": "2024-01-08T00:00Z", "rooms": ["a"], "transitions": {"a": {"a": 0}}, "meetings": [{"id": "a", "zone": "UTC", "local_start": "2024-01-07T09:00", "minutes": 30, "value": 5, "eligible_rooms": ["a"], "people": [], "requires": [], "fold": "earlier"}], "blocks": []}),{"value": 5, "count": 1, "bookings": [{"meeting_id": "a", "room_id": "a", "start": "2024-01-07T09:00:00.000Z", "end": "2024-01-07T09:30:00.000Z"}]}));
